def GT(head, rows, start=1, cls=''):
    """A table revealed cell by cell. A cell is text, or (result, how it was computed)."""
    n = start
    h = ''.join(f'<th>{TX(x)}</th>' for x in head)
    b = ''
    for r in rows:
        tds = ''
        for c in r:
            inner = f'<b class="gv">{TX(c[0])}</b><span class="gm">{TX(c[1])}</span>' if isinstance(c, tuple) else f'<b class="gv">{TX(c)}</b>'
            tds += f'<td>{ST(n, inner)}</td>'
            n += 1
        b += f'<tr>{tds}</tr>'
    return f'<table class="tbl2 steptbl {cls}"><tr>{h}</tr>{b}</table>', n


def CH(x, series, x0, x1, y0, y1, xt, yt, xl='מחיר בפקיעה (S_T)', yl='ש״ח', H=330):
    return dict(x=x, series=series, x0=x0, x1=x1, y0=y0, y1=y1, xt=xt, yt=yt, xl=xl, yl=yl, W=470, H=H)


