def OPTPAIR(code, title_he, story, side, typ, prem, letter, pay_notes, pnl_notes, payvals):
    """Two slides per position: first the payoff, built point by point; then the profit, payoff less premium."""
    K = 100
    f = (lambda s: max(s - K, 0)) if typ == 'call' else (lambda s: max(K - s, 0))
    pay = [(x, side * f(x)) for x in (70, 100, 130)]
    pr = [(x, y - side * prem) for x, y in pay]
    Y, XT, YT = (-40, 40), [70, 80, 90, 100, 110, 120, 130], [-40, -20, 0, 20, 40]
    col = '#0f9d90' if side > 0 else '#ff6a4d'
    marks = [dict(x=x, y=y, t=f'{y:g}'.replace('-', '−'), dy=(-12 if y >= 0 else 22), s=3 + i, c=PAYC) for i, (x, y) in enumerate(pay)]
    S(f's-{code}1', f'{title_he}: התזרים', f'{title_he}: התזרים בפקיעה (Payoff)',
      f'<div class="card qstem"><p>{TX(story)}</p></div><div style="height:8px"></div>'
      + STEPS(CHART([dict(pts=pay, c=PAYC, s=6)], 70, 130, *Y, XT, YT, H=368, xl='מחיר המניה בפקיעה, S_T', yl='תזרים (Payoff)', xs=1, ys=2, marks=marks),
              RL(['<b>ציר אופקי:</b> מחיר המניה בפקיעה, $S_{T}$.', '<b>ציר אנכי:</b> התזרים (Payoff), עדיין בלי הפרמיה. הקו הכהה הוא אפס.'] + pay_notes)), kick='חלק 2 · בנייה בהדרגה')
    marks2 = [dict(x=x, y=y, t=f'{y:g}'.replace('-', '−'), dy=(-12 if y >= 0 else 22), s=2 + i, c=col) for i, (x, y) in enumerate(pr)]
    S(f's-{code}2', f'{title_he}: הרווח', f'{title_he}: הרווח או ההפסד (P&L)',
      STEPS(CHART([dict(pts=pay, c='#c9c4d9', w=3), dict(pts=pr, c=col, s=5)], 70, 130, *Y, XT, YT, H=430, xl='מחיר המניה בפקיעה, S_T', yl='רווח או הפסד (P&L)', marks=marks2), RL(pnl_notes)), kick='חלק 2 · בנייה בהדרגה')


