S('s-swap', 'עסקת החלפה', 'אבן הבניין האחרונה: עסקת החלפה (Swap)',
  '<div class="row eq2 top">'
  + DEF('עסקת החלפה (Swap)', 'הסכם להחליף תזרימים בכמה מועדים עתידיים.', 'חברה משלמת ריבית משתנה על הלוואה, ורוצה ודאות. היא מסכמת עם בנק: היא תשלם לו 4.5%, והוא ישלם לה את הריבית המשתנה.', trm='swap')
  + DEF('ערך נקוב (Notional amount)', 'הסכום שעליו מחושבת הריבית. לרוב הוא איננו עובר בין הצדדים.', 'על 10,000,000 ש״ח, הפרש של 1% בין הריביות שווה 100,000 ש״ח בשנה.', trm='notional') + '</div>'
  + GT(['הריבית המשתנה השנה', 'החברה משלמת למלווה', 'נטו מול הבנק', 'העלות נטו'], [['3.5%', '3.5%', ('משלמת 1%', '$4.5 − 3.5$'), ('4.5%', '$3.5 + 1$')], ['6%', '6%', ('מקבלת 1.5%', '$6 − 4.5$'), ('4.5%', '$6 − 1.5$')]])[0]
  + BAND('note', 'המספרים להמחשה, בלי מרווח של הבנק. נרחיב בשיעור 9.', 9), kick='חלק 2 · הגדרה והדגמה')

S('s-compare', 'השוואת המכשירים', 'סיכום: ארבעה מכשירים, ומי מחויב למה',
  TABLE(['מכשיר', 'מי מחויב', 'תשלום היום', 'אם המחיר נע לטובתכם'], [
      ['חוזה אקדמה (Forward)', 'שני הצדדים', 'אין', 'מוותרים על השיפור'],
      ['חוזה עתידי (Futures)', 'שני הצדדים', 'ביטחונות (Margin), לא מחיר', 'מוותרים על השיפור'],
      ['אופציה (Option)', 'הכותב (Short) בלבד', 'פרמיה (Premium) מהקונה (Long)', 'נהנים מהשיפור, פחות הפרמיה'],
      ['עסקת החלפה (Swap)', 'שני הצדדים', 'לרוב אין', 'מוותרים על השיפור']], 'big')
  + TOON('hands', 'זכות עולה כסף. חובה עולה עצבים.'), kick='חלק 2 · סיכום')

MCS('m-2', 'בדיקת הבנה: חלק 2', 'בדיקת הבנה', [
    mc('q21', 'מי מחזיק בזכות באופציה (Option)?', ['הקונה (Long)', 'הכותב (Short)', 'המסלקה (Clearing house)', 'שניהם'], 0, 'הקונה משלם פרמיה ומחליט. הכותב מחויב אם הקונה מממש.'),
    mc('q22', 'משקיע מחזיק אופציית מכר אמריקאית (American Put). המניה ירדה הרבה. מה נכון?', ['מותר לו לממש כבר היום', 'הוא חייב לממש היום', 'מותר לו לממש רק בפקיעה', 'הכותב מחליט'], 0, 'אמריקאית ניתנת למימוש בכל מועד. זו זכות, לא חובה.'),
    mc('q23', 'מה ההבדל בין חוזה אקדמה (Forward) לאופציית רכש (Call), מנקודת מבט הקונה?', ['באופציה יש זכות, ומשלמים פרמיה', 'בחוזה אקדמה משלמים פרמיה', 'אין הבדל', 'באופציה שני הצדדים מחויבים'], 0, 'בחוזה אקדמה הקונה מחויב ואינו משלם. באופציה הוא משלם ואינו מחויב.')])
